def can_access(user, doc):
    try:
        return policy_service.allowed(user.id, doc.id, timeout=0.5)
    except Exception:
        log.exception("policy check failed", extra={"user": user.id, "doc": doc.id})
        return False                   # falha fechada

@app.errorhandler(Exception)
def on_error(e):
    rid = uuid4().hex
    log.exception("unhandled error", extra={"request_id": rid})
    return {"error": "internal error", "request_id": rid}, 500

