def test_denies_when_policy_service_is_down(monkeypatch, user, doc):
    monkeypatch.setattr(policy_service, "allowed", lambda *a, **k: (_ for _ in ()).throw(TimeoutError()))
    assert can_access(user, doc) is False

def test_error_response_has_no_internals(client, monkeypatch):
    monkeypatch.setattr(db, "query", lambda *a, **k: (_ for _ in ()).throw(RuntimeError("relation users_secret does not exist")))
