test("a failed credit rolls back the debit", async () => {
  jest.spyOn(accounts, "credit").mockRejectedValue(new Error("boom"));
  const before = await accounts.balance(from);
  await expect(transfer(from, to, 50)).rejects.toThrow();
  expect(await accounts.balance(from)).toBe(before);
});
